import 'dart:async';
import 'package:flutter/material.dart';

/// Fixed exercise infrastructure. Do not edit this file.
/// Gates and delays use real time, including in widget tests.
final class Backend {
  Backend({
    this.holdOpens = false,
    this.holdCloses = false,
    this.openDelay = const Duration(milliseconds: 20),
    this.closeDelay = const Duration(milliseconds: 20),
  });

  final bool holdOpens;
  final bool holdCloses;
  final Duration openDelay;
  final Duration closeDelay;
  final events = <String>[];
  final _resources = <Resource>[];
  final _opens = <String, List<Completer<void>>>{};
  final _closes = <String, List<Completer<void>>>{};
  final _failures = <String, int>{};
  int useAfterClose = 0;

  int get liveResources => _resources.where((r) => !r._closed).length;

  /// Fail the next acquisition of this id, after its gate/delay completes.
  void failNextOpen(String id) =>
      _failures.update(id, (n) => n + 1, ifAbsent: () => 1);

  Future<void> _wait(String id, bool hold, Duration delay,
          Map<String, List<Completer<void>>> gates) =>
      Zone.root.run(() {
        if (!hold) return Future<void>.delayed(delay);
        final gate = Completer<void>();
        gates.putIfAbsent(id, () => []).add(gate);
        return gate.future;
      });

  /// Release all currently pending acquisitions; future attempts still wait.
  void releaseOpen(String id) => _release(id, _opens);
  void releaseClose(String id) => _release(id, _closes);

  void _release(String id, Map<String, List<Completer<void>>> gates) {
    for (final gate in gates.remove(id) ?? <Completer<void>>[]) {
      Zone.root.run(gate.complete);
    }
  }

  Future<Resource> open(String id) async {
    events.add('open:$id');
    final fail = (_failures[id] ?? 0) > 0;
    if (fail) _failures[id] = _failures[id]! - 1;
    await _wait(id, holdOpens, openDelay, _opens);
    if (fail) {
      events.add('failed:$id');
      throw StateError('Cannot open $id');
    }
    final resource = Resource._(this, id);
    _resources.add(resource);
    events.add('opened:$id');
    return resource;
  }
}

final class Resource {
  Resource._(this._backend, this.id);
  final Backend _backend;
  final String id;
  bool _closing = false;
  bool _closed = false;

  void use(String action) {
    if (_closing || _closed) {
      _backend.useAfterClose++;
      throw StateError('Use after close: $id ($action)');
    }
    _backend.events.add('use:$id:$action');
  }

  Future<void> close() async {
    if (_closing || _closed) throw StateError('Double close: $id');
    _closing = true;
    _backend.events.add('close:$id');
    await _backend._wait(
        id, _backend.holdCloses, _backend.closeDelay, _backend._closes);
    _closed = true;
    _backend.events.add('closed:$id');
  }
}

/// Mount this exact widget in the ready branch with the acquired resource.
/// Its last synchronous use in dispose makes teardown order observable.
final class ResourceChild extends StatefulWidget {
  const ResourceChild({super.key, required this.resource});
  final Resource resource;

  @override
  State<ResourceChild> createState() => _ResourceChildState();
}

final class _ResourceChildState extends State<ResourceChild> {
  @override
  void initState() {
    super.initState();
    widget.resource.use('mount');
  }

  @override
  void dispose() {
    widget.resource.use('dispose');
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Data ${widget.resource.id}', key: const ValueKey('data')),
          TextButton(
            key: const ValueKey('use'),
            onPressed: () => widget.resource.use('tap'),
            child: const Text('Use'),
          ),
        ],
      );
}
